"""Zero-dependency browser UI for ChoreQuest."""
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse, parse_qs
from pathlib import Path
import html, uuid
import shutil
import os
import json
from chorequest.executor import Executor
from chorequest.chores import FolderChore
from chorequest.mapping import folder_action

ROOT = Path(__file__).parent; DATA = ROOT / "runtime" / "sandbox_folder"
def reset_data():
    if DATA.exists(): shutil.rmtree(DATA)
    shutil.copytree(ROOT / "sample_data" / "messy_folder", DATA)
reset_data(); session = uuid.uuid4().hex[:8]; chore = FolderChore(DATA, Executor(DATA, session))

class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        global chore, session
        action = parse_qs(urlparse(self.path).query).get("action", [""])[0]
        if action == "reset":
            reset_data(); session = uuid.uuid4().hex[:8]; chore = FolderChore(DATA, Executor(DATA, session))
        expected = None
        if chore.next_item():
            ext = chore.next_item().suffix.lower()
            expected = "Archive" if ext in (".zip", ".rar", ".7z") else ("Media" if ext in (".jpg", ".png", ".mp3", ".wav", ".mp4") else "Documents")
        success = False
        if action in ("a", "s", "d") and chore.next_item() and folder_action(action) == expected:
            chore.apply(action); success = True
        item = chore.next_item(); remaining = len(chore.items)
        name = item.name if item else "Complete!"
        if parse_qs(urlparse(self.path).query).get("ajax", [""])[0] == "1":
            payload = json.dumps({"name": name, "remaining": remaining, "complete": not bool(item), "success": success, "expected": expected})
            self.send_response(200); self.send_header("Content-Type", "application/json"); self.end_headers(); self.wfile.write(payload.encode()); return
        body = f'''<!doctype html><meta name="viewport" content="width=device-width"><title>ChoreQuest // Sorting Protocol</title>
        <style>
        :root{{--black:#080808;--red:#d71920;--red2:#ff3b30;--white:#f4f4f0;--silver:#a7a9ac;--line:#3b3b3b}}*{{box-sizing:border-box}}body{{margin:0;background:var(--black);color:var(--white);font:14px ui-monospace,SFMono-Regular,Menlo,monospace;min-height:100vh}}main{{max-width:1120px;margin:auto;padding:26px 24px}}header{{border-bottom:1px solid var(--line);padding-bottom:18px;display:flex;justify-content:space-between;align-items:flex-end}}.brand{{letter-spacing:5px;font:700 25px Arial;color:var(--white)}}.brand span{{color:var(--red)}}.sub{{color:var(--silver);letter-spacing:2px;font-size:11px;margin-top:7px}}.hud{{display:flex;gap:9px}}.stat{{border:1px solid var(--line);padding:9px 13px;min-width:92px;text-align:center;background:#151515}}.stat b{{display:block;color:var(--red2);font:bold 19px Arial;margin-top:3px}}.layout{{display:grid;grid-template-columns:1fr 270px;gap:18px;margin-top:18px}}.arena,.side{{border:1px solid var(--line);background:#101010}}.arena{{padding:23px;min-height:520px;display:flex;flex-direction:column}}.side{{padding:18px}}.eyebrow{{color:var(--red2);font-size:11px;letter-spacing:2px}}.title{{font:700 20px Arial;letter-spacing:1px;margin:8px 0 20px}}.target{{flex:1;display:flex;flex-direction:column;justify-content:center;align-items:center;border:1px dashed #575757;background:repeating-linear-gradient(135deg,#101010,#101010 8px,#141414 8px,#141414 16px);position:relative;overflow:hidden}}.target:before{{content:'INCOMING';position:absolute;top:13px;left:15px;color:#555;letter-spacing:3px;font-size:10px}}.file{{border:2px solid var(--red);background:var(--black);padding:22px 28px;min-width:55%;text-align:center;box-shadow:8px 8px 0 var(--red);animation:drop .35s ease-out;cursor:grab}}.file:active{{cursor:grabbing}}.file.dragging{{opacity:.5}}@keyframes drop{{from{{transform:translateY(-24px);opacity:0}}to{{transform:none;opacity:1}}}}.file .icon{{font-size:38px;color:var(--red)}}.file h2{{font:700 24px Arial;word-break:break-word;margin:10px 0;color:var(--white)}}.file small{{color:var(--silver)}}.zones{{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:20px}}button{{font:700 12px ui-monospace,monospace;letter-spacing:1px;color:var(--white);background:#191919;border:1px solid #666;padding:15px 8px;cursor:pointer;transition:.12s}}button:hover,button:focus{{border-color:var(--red);background:#291010;transform:translateY(-3px)}}button:active{{transform:translateY(2px)}}button.over{{border-color:var(--red2);background:#291010}}button .key{{display:inline-block;border:1px solid var(--silver);color:var(--silver);padding:2px 6px;margin-right:5px}}.progress{{height:7px;background:#2b2b2b;margin:18px 0 8px}}#bar{{height:100%;background:var(--red);transition:.25s}}#feed{{height:34px;text-align:center;padding-top:12px;color:var(--silver)}}.feed-good{{color:#fff!important}}.feed-bad{{color:var(--red2)!important}}.side h3{{font:700 13px Arial;letter-spacing:2px;border-bottom:1px solid var(--line);padding-bottom:12px;margin-top:0}}.side p{{color:var(--silver);line-height:1.6}}.side strong{{color:var(--white)}}.ledger{{margin-top:22px;border-top:1px solid var(--line);padding-top:14px;font-size:11px;color:var(--silver)}}.reset{{display:block;color:var(--silver);margin-top:18px;text-decoration:none;border:1px solid var(--line);padding:10px;text-align:center}}.reset:hover{{color:var(--red2);border-color:var(--red)}}@media(max-width:760px){{.layout{{grid-template-columns:1fr}}.side{{display:none}}header{{align-items:flex-start;gap:15px;flex-direction:column}}}}
        </style><main><header><div><div class="brand">CHORE<span>QUEST</span></div><div class="sub">SORTING PROTOCOL // SANDBOXED OPERATIONS</div></div><div class="hud"><div class="stat">SCORE<b id="score">0</b></div><div class="stat">STREAK<b id="combo">0</b></div><div class="stat">LIVES<b id="lives">3</b></div><div class="stat">TIME<b id="time">45</b></div></div></header><div class="layout"><section class="arena"><div class="eyebrow">MISSION 01 / FOLDER TRIAGE</div><div class="title">CLASSIFY THE INCOMING FILE</div><div class="target"><div class="file" draggable="true" ondragstart="drag(event)"><div class="icon">▣</div><h2 id="name">{html.escape(name)}</h2><small id="remaining">{remaining} TARGETS REMAINING</small></div></div><div class="progress"><div id="bar" style="width:{(8-remaining)*12.5}%"></div></div><div class="zones"><button id="zone0" ondragover="allow(event)" ondrop="drop(event,'a')" onclick="play('a')"><span class="key">1</span> DOCUMENTS</button><button id="zone1" ondragover="allow(event)" ondrop="drop(event,'s')" onclick="play('s')"><span class="key">2</span> MEDIA</button><button id="zone2" ondragover="allow(event)" ondrop="drop(event,'d')" onclick="play('d')"><span class="key">3</span> ARCHIVE</button></div><div id="feed">ARROWS SELECT A ZONE · SPACE / ENTER DEPLOY · DRAG ALSO WORKS</div></section><aside class="side"><h3>FIELD MANUAL</h3><p><strong>Arcade controls</strong><br>← / → move selector<br>Space or Enter deploy<br>1 / 2 / 3 quick-select<br>Mouse click or drag-and-drop</p><p><strong>Scoring</strong><br>Correct classification: +100<br>Streak bonus grows with speed.<br>Wrong classification costs a life.</p><p><strong>Real operation</strong><br>Every correct move is executed inside the sandbox and written to a rollback journal.</p><div class="ledger">SESSION<br><strong>{session}</strong><br><br>MODE<br><strong>FOLDER TRIAGE</strong></div><a class="reset" href="/?action=reset">RESET MISSION</a></aside></div></main><script>let score=0,combo=0,lives=3,seconds=45,active=true,selected=0;const total=8,keys=['a','s','d'];function paint(){{for(let i=0;i<3;i++)document.getElementById('zone'+i).classList.toggle('over',i===selected)}}paint();function allow(e){{e.preventDefault();e.currentTarget.classList.add('over')}}function drop(e,k){{e.preventDefault();e.currentTarget.classList.remove('over');play(k)}}function drag(e){{e.dataTransfer.setData('text/plain','file')}}function play(k){{if(!active)return;fetch('/?action='+k+'&ajax=1').then(r=>r.json()).then(d=>{{const f=document.getElementById('feed');if(!d.success&&!d.complete){{combo=0;lives--;document.getElementById('combo').textContent=combo;document.getElementById('lives').textContent=lives;f.textContent='✕ WRONG ZONE // LIFE LOST';f.className='feed-bad';if(lives<=0){{active=false;f.textContent='GAME OVER // RESET TO REDEPLOY'}}return}}if(d.complete){{active=false;document.getElementById('feed').textContent='◆ MISSION COMPLETE // ALL OPERATIONS EXECUTED';return}}score+=100+combo*25;combo++;document.getElementById('score').textContent=score;document.getElementById('combo').textContent=combo;document.getElementById('name').textContent=d.name;document.getElementById('remaining').textContent=d.remaining+' TARGETS REMAINING';document.getElementById('bar').style.width=((total-d.remaining)/total*100)+'%';f.textContent='✓ MOVE EXECUTED // JOURNAL UPDATED';f.className='feed-good'}})}}document.addEventListener('keydown',e=>{{const k=e.key.toLowerCase();if(k==='arrowleft'){{e.preventDefault();selected=(selected+2)%3;paint()}}else if(k==='arrowright'){{e.preventDefault();selected=(selected+1)%3;paint()}}else if(k===' '||k==='enter'){{e.preventDefault();play(keys[selected])}}else if(k==='1'||k==='2'||k==='3'){{selected=Number(k)-1;paint();play(keys[selected])}}else if(keys.includes(k))play(k)}});setInterval(()=>{{if(active&&seconds>0){{seconds--;document.getElementById('time').textContent=seconds;if(seconds===0){{active=false;document.getElementById('feed').textContent='TIME EXPIRED // RESET TO REDEPLOY';}}}}}},1000);</script>'''
        self.send_response(200); self.send_header("Content-Type", "text/html"); self.end_headers(); self.wfile.write(body.encode())
    def log_message(self, *_): pass

if __name__ == "__main__":
    port = int(os.environ.get("PORT", "5000"))
    print(f"ChoreQuest running at http://localhost:{port}")
    HTTPServer(("0.0.0.0", port), Handler).serve_forever()
